<?php
namespace Tests\Feature;
use App\Models\{User,ConnectedAdAccount,Campaign,PerformanceMetric};
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Carbon;
use Tests\TestCase;
class AudienceSaturationTest extends TestCase{
 use DatabaseTransactions;
 private function fixture():array{$u=User::factory()->create();$a=ConnectedAdAccount::create(['user_id'=>$u->id,'provider'=>'meta','external_account_id'=>uniqid(),'account_name'=>'Fixture','currency'=>'USD','timezone'=>'UTC','access_token'=>'fixture']);$c=Campaign::create(['connected_ad_account_id'=>$a->id,'provider'=>'meta','external_campaign_id'=>uniqid(),'name'=>'Fixture','currency'=>'USD']);return[$u,$a,$c];}
 private function row($a,$c,array $extra=[]):PerformanceMetric{return PerformanceMetric::create($extra+['metadata'=>['outcome_contract'=>['version'=>'source-outcomes-1','provider'=>'meta','count_metric'=>'synthetic-purchase','value_metric'=>'synthetic-purchase-value','attribution_basis'=>'synthetic-only','value_truth'=>'provider_reported_not_verified_sales','cross_source_equivalence'=>false],'normalization_version'=>'strict-operands-1','account_metadata_source'=>'provider-discovery-explicit-1','metric_definition'=>['version'=>'meta-pixel-purchase-1','normalization'=>'strict-meta-operands-1','account_metadata_source'=>'meta-discovery-explicit-1','conversion'=>'offsite_conversion.fb_pixel_purchase','value'=>'offsite_conversion.fb_pixel_purchase']],'connected_ad_account_id'=>$a->id,'campaign_id'=>$c->id,'provider'=>'meta','currency'=>'USD','date'=>now()->subDay()->toDateString(),'spend'=>100,'impressions'=>1000,'clicks'=>50,'conversions'=>5,'reach'=>600,'frequency'=>1.666667]);}
 private function seedSeries($a,$c,int $n=40):void{for($i=0;$i<$n;$i++){$f=1.0+($i*7%$n)/$n*3.0;$imp=10000+($i*37%11)*100;$ctr=($f<2.5?0.02:0.02-0.008*($f-2.5))+((($i*13%7)-3)*0.0001);$this->row($a,$c,['date'=>now()->subDays($n-$i)->toDateString(),'frequency'=>$f,'impressions'=>$imp,'clicks'=>max(1,round($imp*$ctr)),'spend'=>100+$i,'conversions'=>5+$i%3,'reach'=>5000]);}}
 public function test_one_entity_estimate_is_labelled_estimated_and_scoped():void{Carbon::setTestNow(Carbon::parse('2026-11-23T12:00:00Z'));try{[$u,$a,$c]=$this->fixture();$this->seedSeries($a,$c);$r=$this->actingAs($u,'sanctum')->getJson('/api/v1/analytics/audience-saturation?account_id='.$a->id.'&entity_level=campaign&entity_id='.$c->id.'&metric=ctr&days=60')->assertOk()->assertJsonPath('data.type','ESTIMATED')->assertJsonPath('data.entity_id',$c->id);$this->assertSame('ok',$r->json('data.status'));$this->assertNotNull($r->json('data.interval.kind'));$this->assertStringContainsString('not_causal',$r->json('data.interval.kind'));$this->assertEqualsWithDelta(2.5,$r->json('data.saturation_threshold'),0.4);$this->assertStringContainsString('never averaged',$r->json('data.relevance_note'));}finally{Carbon::setTestNow();}}
 public function test_foreign_account_is_404_and_short_history_is_refused():void{Carbon::setTestNow(Carbon::parse('2026-11-23T12:00:00Z'));try{[$u,$a,$c]=$this->fixture();[$o,$b,$fc]=$this->fixture();$this->seedSeries($a,$c,10);$this->actingAs($u,'sanctum')->getJson('/api/v1/analytics/audience-saturation?account_id='.$b->id.'&entity_level=campaign&entity_id='.$fc->id.'&metric=ctr')->assertNotFound();$r=$this->getJson('/api/v1/analytics/audience-saturation?account_id='.$a->id.'&entity_level=campaign&entity_id='.$c->id.'&metric=cpa');$r->assertOk()->assertJsonPath('data.status','insufficient_data')->assertJsonPath('data.saturation_threshold',null);}finally{Carbon::setTestNow();}}
}
